"""Generate offline therapy pages from the original, sourced catalog. Run after catalog edits."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent
DATA=json.loads((ROOT/'therapy-catalog.json').read_text())
def e(s):return html.escape(str(s),quote=True)
def paras(items):return ''.join('<li>'+e(x)+'</li>' for x in items)
CSS='''
:root{font:12pt/1.55 Arial,Helvetica,sans-serif;color:#29453c;background:#fff9ed}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#d8f5e8 0,transparent 45%),#fff9ed}header{padding:24px max(5vw,20px);background:linear-gradient(115deg,#d0f2e1,#eaf8dc 55%,#ffe2b5);border-top:7px solid #ff8a00;border-bottom:1px solid #9bd5bc}h1,h2,h3,h4{font-size:14pt;line-height:1.4;color:#075e52}h1{margin:8px 0}h2{margin-top:0}main{max-width:1100px;margin:24px auto;padding:0 20px}a{color:#80501c;text-underline-offset:3px}.backlinks{display:flex;flex-wrap:wrap;gap:18px}.eyebrow{color:#614633}.pill{display:inline-block;padding:4px 10px;border:1px solid #e8b564;background:#ffe8b7;border-radius:20px;margin:4px 6px 4px 0}.modality-nav{display:flex;gap:6px;overflow-x:auto;padding:12px 0;max-width:1100px;margin:auto}.modality-nav a{flex:0 0 auto;border:1px solid #9acdb2;background:#effaf1;color:#075e52;padding:8px 12px;border-radius:7px;text-decoration:none;font-size:14pt;font-weight:bold}.modality-nav a[aria-current=page]{background:#ff8a00;border-color:#df7500;color:#392b1e}.page-tabs{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}button{font:inherit;color:#075e52;cursor:pointer;padding:10px 14px;border-radius:7px;border:1px solid #aac7b3;background:#fffef9}button:hover{background:#e2f4e8}button[aria-selected=true],button.primary{background:#ff8a00;color:#392b1e;border-color:#dd7500}button:focus-visible,a:focus-visible,textarea:focus-visible{outline:3px solid #ff8a00;outline-offset:3px}.card{background:#fffef9;border:1px solid #cee0cf;border-radius:10px;padding:22px;margin:16px 0;min-width:0}.notice{border-left:4px solid #ec8b09;background:#fff1d9;padding:14px 18px;border-radius:7px;margin:16px 0}.muted{color:#57685d}.association-list{padding-left:24px}.association-list li{margin:8px 0}.page-panel[hidden]{display:none}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:16px}.handout-header{padding-bottom:12px;border-bottom:2px solid #ff8a00}.handout-steps li{margin:12px 0}.example{padding:12px;background:#edf8ef;border-radius:7px}label{display:block;font-weight:bold;margin:16px 0 6px}textarea{width:100%;min-height:88px;border:1px solid #a2bfae;background:white;border-radius:7px;padding:10px;font:inherit;resize:vertical}.print-note{display:none;white-space:pre-wrap;overflow-wrap:anywhere;min-height:48px;border-bottom:1px solid #aaa;padding:8px 0}.print-controls{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.evidence-item{border-left:4px solid #189b64}.evidence-item p{margin:10px 0}.evidence-item a{overflow-wrap:anywhere}.handout-footer{border-top:1px solid #bacdbd;margin-top:20px;padding-top:10px}.primary-target{font-weight:bold}.print-area{break-inside:auto}footer{max-width:1100px;margin:24px auto;padding:0 20px;color:#57685d}@media(max-width:700px){.two-col{grid-template-columns:1fr}header{padding:18px}main{padding:0 14px}.card{padding:16px}.page-tabs button{flex:1 0 auto}.modality-nav{padding-left:4px}.backlinks{gap:10px}}
@page{size:auto;margin:16mm}@media print{body{background:white;color:#111;font-size:12pt}header,.modality-nav,.page-tabs,.screen-only,footer,button{display:none!important}main{max-width:none;margin:0;padding:0}.card{border:0;box-shadow:none;padding:0;margin:0}h1,h2,h3,h4{color:#111}textarea{display:none}.print-note{display:block}.notice{border:1px solid #aaa;background:white}.example{background:white;border:1px solid #aaa}.handout-header{border-color:#444}a{color:#111}.pill{background:white}.two-col{display:block}body.printing main>*{display:none!important}body.printing main>.page-panel:has(.print-target){display:block!important}body.printing .page-panel>*:not(.print-target){display:none!important}body.printing .print-target{display:block!important}body.printing .print-target[hidden]{display:block!important}.handout-footer{font-size:12pt}.print-note{orphans:3;widows:3}h2,h3,label{break-after:avoid}li{break-inside:avoid}}
'''
JS='''
'use strict';
const validTabs=['overview','tools','discussion','evidence'];
function showPageTab(id,update=true){if(!validTabs.includes(id))id='overview';for(const panel of document.querySelectorAll('.page-panel'))panel.hidden=panel.id!==id;for(const b of document.querySelectorAll('[data-page-tab]')){const active=b.dataset.pageTab===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1}if(update)history.replaceState(null,'','#'+id)}
for(const b of document.querySelectorAll('[data-page-tab]')){b.addEventListener('click',()=>showPageTab(b.dataset.pageTab));b.addEventListener('keydown',event=>{const tabs=[...document.querySelectorAll('[data-page-tab]')];const i=tabs.indexOf(b);let n;if(event.key==='ArrowRight')n=(i+1)%tabs.length;else if(event.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')n=0;else if(event.key==='End')n=tabs.length-1;else return;event.preventDefault();tabs[n].focus();showPageTab(tabs[n].dataset.pageTab)})}
function syncPrintNotes(){for(const field of document.querySelectorAll('textarea[data-print-note]'))document.getElementById(field.dataset.printNote).textContent=field.value||'__________________________________________________'}
for(const field of document.querySelectorAll('textarea[data-print-note]'))field.addEventListener('input',syncPrintNotes);
function printResource(id){const target=document.getElementById(id);if(!target?.classList.contains('print-area'))return;for(const old of document.querySelectorAll('.print-target'))old.classList.remove('print-target');target.classList.add('print-target');syncPrintNotes();document.body.classList.add('printing');window.print()}
for(const b of document.querySelectorAll('[data-print-resource]'))b.addEventListener('click',()=>printResource(b.dataset.printResource));
function finishPrint(){document.body.classList.remove('printing');for(const old of document.querySelectorAll('.print-target'))old.classList.remove('print-target')}
window.addEventListener('afterprint',finishPrint);window.addEventListener('beforeprint',syncPrintNotes);window.addEventListener('hashchange',()=>showPageTab(location.hash.slice(1),false));
syncPrintNotes();showPageTab(location.hash.slice(1),false);
'''
def links(current):return '<nav class="modality-nav" aria-label="Therapy modalities">'+''.join('<a href="therapy-'+e(c['id'])+'.html"'+(' aria-current="page"' if c['id']==current else '')+' title="'+e(c['name'])+'">'+e(c['short'])+'</a>' for c in DATA['modalities'])+'</nav>'
def fields(id,questions):
 return ''.join('<label for="'+id+'-'+str(i)+'">'+e(q)+'</label><textarea id="'+id+'-'+str(i)+'" data-print-note="'+id+'-'+str(i)+'-print" placeholder="Optional practice notes — stay with what you want to discuss."></textarea><div class="print-note" id="'+id+'-'+str(i)+'-print" aria-hidden="true"></div>' for i,q in enumerate(questions))
for c in DATA['modalities']:
 id=c['id'];h=c['handout'];f='<p class="handout-footer">'+e(c['short'])+' · Original supportive material · Reviewed '+DATA['checked']+'<br>Use alongside your agreed care plan. This handout is not a complete therapy protocol. If you feel unsafe or symptoms worsen, follow your care plan and contact your care team or local emergency services as appropriate.</p>'
 associations='<ul class="association-list">'+paras(c['targets'])+'</ul>'
 if c['diagnosisIds']:associations+='<p>Toolkit diagnosis links: '+', '.join('<a href="index.html#diagnoses/'+e(d)+'">'+e(d.replace('-',' ').upper() if d in ['mdd','gad','ocd','adhd','ptsd','odd'] else d.replace('-',' '))+'</a>' for d in c['diagnosisIds'])+'</p>'
 evs=''
 for item in c['evidence']:
  src=DATA['sources'][item['source']];evs+='<article class="card evidence-item" data-source="'+e(item['source'])+'"><h3>'+e(src['title'])+'</h3><span class="pill">'+e(src['type'])+'</span><span class="pill">'+e(src['year'])+'</span><p><strong>Clinical finding:</strong> '+e(item['summary'])+'</p><p><strong>Limits / applicability:</strong> '+e(item['limits'])+'</p><a href="'+e(src['url'])+'" target="_blank" rel="noopener noreferrer">Open source</a></article>'
 out='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; connect-src \'none\'; img-src data:; base-uri \'none\'; form-action \'none\'"><title>'+e(c['short'])+' | PMHNP Clinical Toolkit</title><style>'+CSS+'</style></head><body><header><div class="backlinks"><a href="index.html#therapies">← Search all therapies</a><a href="index.html#diagnoses">Diagnosis workspace</a></div><p class="eyebrow">PMHNP / FNP · Therapy companion</p><h1>'+e(c['name'])+'</h1><p>'+e(c['overview'])+'</p>'+links(id)+'</header><main><nav class="page-tabs" role="tablist" aria-label="Therapy page sections">'+''.join('<button id="page-tab-'+x+'" data-page-tab="'+x+'" role="tab" aria-controls="'+x+'" aria-selected="'+str(i==0).lower()+'" tabindex="'+('0' if i==0 else '-1')+'">'+t+'</button>' for i,(x,t) in enumerate([('overview','Overview & diagnoses'),('tools','Patient tools & print'),('discussion','Discussion guide'),('evidence','Evidence & research')]))+'</nav>'
 out+='<section class="page-panel" id="overview" role="tabpanel" aria-labelledby="page-tab-overview"><article class="card"><h2>Primary treatment associations</h2>'+associations+'<p><strong>Population / context:</strong> '+e(c['population'])+'</p><p><strong>How the therapy works:</strong> '+e(c['approach'])+'</p></article><div class="notice"><strong>Fit and scope:</strong> '+e(c['guardrail'])+'</div><article class="card"><h2>Using this with therapist-led care</h2><p>Choose a shared goal, check that the practice matches the therapist’s plan, and review what happened. The printable materials are original adjunct tools, not validated stand-alone treatments or copied therapy worksheets.</p><p>Use the Patient tools tab to show or print the handout, and the Discussion guide to prepare the next visit. The Evidence tab shows sources and their limits.</p></article></section>'
 out+='<section class="page-panel" id="tools" role="tabpanel" aria-labelledby="page-tab-tools" hidden><div class="screen-only"><p>Show this page to a patient or print a blank/optionally completed copy. Notes stay in page memory and clear when you leave or reload; printed or saved PDFs contain anything you enter.</p><div class="print-controls"><button class="primary" data-print-resource="patient-handout">Print / save patient handout</button></div></div><article class="card print-area" id="patient-handout"><div class="handout-header"><p>'+e(c['short'])+' · Between-session support</p><h2>'+e(h['title'])+'</h2></div><p>'+e(c['overview'])+'</p><ol class="handout-steps">'+paras(h['steps'])+'</ol><p class="example"><strong>For example:</strong> '+e(h['example'])+'</p>'+fields('practice',h['prompts'])+'<p><strong>Plan with your therapist:</strong> '+e(c['guardrail'])+'</p>'+f+'</article></section>'
 out+='<section class="page-panel" id="discussion" role="tabpanel" aria-labelledby="page-tab-discussion" hidden><div class="screen-only print-controls"><button class="primary" data-print-resource="discussion-handout">Print / save discussion guide</button></div><article class="card print-area" id="discussion-handout"><div class="handout-header"><p>'+e(c['short'])+' · Patient and clinician discussion</p><h2>Make our next conversation useful</h2></div><p>You can leave any question blank and decide what you want to share. No detailed trauma account or identifying information is needed.</p>'+fields('discussion',c['discussion']+['What small practice have we agreed, and when will we review it?'])+f+'</article></section>'
 out+='<section class="page-panel" id="evidence" role="tabpanel" aria-labelledby="page-tab-evidence" hidden><article class="card"><h2>Evidence & research</h2><p>Selected primary studies, official guidelines and education sources; checked '+DATA['checked']+'. Source type and limitations are shown separately. This is not a systematic review or a claim that every therapy is equally effective for every diagnosis.</p><p><strong>Population / context:</strong> '+e(c['population'])+'</p><p>The evidence below concerns the full therapy or clinical guidance. The original companion handouts have not been independently validated.</p></article>'+evs+'</section></main><footer>PMHNP Clinical Toolkit · No trackers, remote fonts, or network processing. External sources load only when opened. Content review: '+DATA['checked']+'.</footer><script>'+JS+'</script></body></html>'
 (ROOT/('therapy-'+id+'.html')).write_text(out)
print('Generated',len(DATA['modalities']),'offline therapy pages')
